    expect({outcome, logged: errors.length}).toEqual({outcome: 'hi', logged: 0});
  });

  // A turn with the given hooks installed, recording which sessions were saved.
  const turnWithHooks = async (hooks: unknown): Promise<{outcome: string; saved: string[]}> => {
    const saved: string[] = [];
    const store = recordingSessionStore(session => void saved.push(session.sessionId));
    const orchestrator = createChatOrchestrator(answering('hi'), writeSignalPromptBuilder, undefined, {
      sessionStore: store,
      hooks: hooks as never,
    });

    const outcome = await orchestrator
      .processMessage(sessionWith('hello'))
      .catch((error: Error) => `threw: ${error.message}`);

    return {outcome, saved};
  };

  it('saves even when an afterSession hook throws', async () => {
    const result = await turnWithHooks({
      afterSession: () => {
        throw new Error('hook exploded');
      },
    });

    expect(result).toEqual({outcome: 'threw: hook exploded', saved: ['s1']});
  });

  it('saves once and still rethrows when a beforeSession hook throws', async () => {
    const result = await turnWithHooks({
      beforeSession: () => {
        throw new Error('span refused');
      },
    });

    expect(result).toEqual({outcome: 'threw: span refused', saved: ['s1']});
  });
});

